{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C51"],
      "claim": "Delpazolid, the closest analogue sharing the oxazolidinone-hydroxymethyl and fluorophenyl core, showed 99.75% absolute oral bioavailability in humans after 800 mg PO versus IV.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Linezolid, a closely related oxazolidinone antibiotic, is 100% bioavailable after oral administration in humans.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Contezolid, another oxazolidinone with a modified side chain, showed F = 0.64 in healthy subjects, still well above the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "YH4808, a linezolid-like oxazolidinone with a thiomorpholine and acetamide side chain, had low absolute bioavailability of 10.1%, showing that some oxazolidinone modifications can reduce F.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C18"],
      "claim": "Cadazolid, a larger oxazolidinone-fluoroquinolone hybrid, had very low oral bioavailability, but it is structurally much more distant from the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is an oxazolidinone with the same 5-hydroxymethyl-oxazolidinone and fluorophenyl motif as delpazolid, which is essentially completely bioavailable in humans; linezolid and contezolid also support high F. The low-F oxazolidinones differ in key side chains or are much larger hybrids and have lower transferability. Thus high F is better supported.",
  "evidence_gaps": [
    "No direct absolute bioavailability measurement exists for the query molecule.",
    "Low-F oxazolidinone analogues indicate that bioavailability is structure-sensitive, so the specific triazolyl-pyridine substituent could alter absorption or first-pass metabolism.",
    "No solubility, permeability, or metabolism data are available for the query itself."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

